using Microsoft.Data.Sqlite;using Microsoft.EntityFrameworkCore;using Visitors.Api.Data;using Visitors.Api.Models;using Visitors.Api.Services;
namespace Visitors.Tests;
public sealed class VisitServiceTests:IAsyncLifetime{readonly SqliteConnection c=new("Data Source=:memory:");VisitorsDbContext db=null!;VisitService s=null!;public async Task InitializeAsync(){await c.OpenAsync();db=new(new DbContextOptionsBuilder<VisitorsDbContext>().UseSqlite(c).Options);await db.Database.EnsureCreatedAsync();db.Users.Add(new User{Id=1,Username="security",PasswordHash="x",Role="Security"});db.Visitors.AddRange(new Visitor{Id=1,FullName="A",Email="a@example.com",Phone="1"},new Visitor{Id=2,FullName="B",Email="b@example.com",Phone="2"});db.Visits.AddRange(new Visit{Id=1,Reference="V1",VisitorId=1,HostName="Host",Purpose="Meeting",ScheduledAt=DateTime.UtcNow,CreatedById=1},new Visit{Id=2,Reference="V2",VisitorId=2,HostName="Host",Purpose="Delivery",ScheduledAt=DateTime.UtcNow,CreatedById=1});await db.SaveChangesAsync();s=new(db);}public async Task DisposeAsync(){await db.DisposeAsync();await c.DisposeAsync();}
[Fact]public async Task CheckIn_AssignsBadgeAndTimestamp(){var v=await s.CheckInAsync(1,"B-1");Assert.Equal(VisitStatuses.CheckedIn,v.Status);Assert.NotNull(v.CheckedInAt);}
[Fact]public async Task CheckIn_PreventsBadgeReuse(){await s.CheckInAsync(1,"B-1");await Assert.ThrowsAsync<InvalidOperationException>(()=>s.CheckInAsync(2,"B-1"));}
[Fact]public async Task CheckOut_RequiresCheckedInState(){await Assert.ThrowsAsync<InvalidOperationException>(()=>s.CheckOutAsync(1));}
[Fact]public async Task CheckOut_CompletesVisit(){await s.CheckInAsync(1,"B-1");var v=await s.CheckOutAsync(1);Assert.Equal(VisitStatuses.CheckedOut,v.Status);Assert.NotNull(v.CheckedOutAt);}
}
